package org.fieldnotes.domain
import kotlin.test.*
import kotlinx.datetime.*
import kotlinx.serialization.json.*
class CookingPlanTest {
 private fun plan()=CookingPlan(items=listOf(CookingItem("item","Any item",stages=listOf(CookingStage("a","Long cook",600,check_every_minutes=60),CookingStage("b","Rest",60,wait_minutes=15,after=listOf("a")))),CookingItem("side","Anything else",stages=listOf(CookingStage("c","Finish",30,after=listOf("b"))))))
 @Test fun dependenciesWorkBackwardsAndActualProgressPropagates(){val p=plan();val serve=1794765600L;val first=cookingSchedule(p,serve);assertEquals(serve-705*60,first.first().start);assertEquals(serve,first.last().end);val changed=p.copy(progress=listOf(CookingProgress(serve,"a","running",first.first().start+1800)));assertEquals(serve+1800,cookingSchedule(changed,serve).last().end);assertEquals(serve+86400,cookingSchedule(changed,serve+86400).last().end)}
 @Test fun invalidGraphsFailInsteadOfLooping(){val p=plan();assertFailsWith<IllegalArgumentException>{cookingSchedule(p.copy(items=p.items.map{i->i.copy(stages=i.stages.map{if(it.id=="a")it.copy(after=listOf("c"))else it})}),1794765600)};assertFailsWith<IllegalArgumentException>{cookingSchedule(p.copy(items=listOf(CookingItem("i","x",stages=listOf(CookingStage("s","x",20160,offset_minutes=-20160,wait_minutes=20160),CookingStage("t","y",20160,wait_minutes=1,after=listOf("s")))))),1794765600)}}
 @Test fun recurringDinnerSchedulesBeforeItsDayAndDoneSuppressesItsCues(){val zone=TimeZone.UTC;val serve=LocalDateTime(2026,11,15,6,0).toInstant(zone).epochSeconds;val p=plan();val r=Record("meal","event",1,obj("title" to "Dinner".j(),"meal_kind" to "dinner".j(),"all_day" to JsonPrimitive(false),"starts_at" to serve.j(),"ends_at" to JsonNull,"meal_plan" to cookingData(p),"recurrence" to repeatData(EventRepeat("weekly",weekdays=listOf(7),zone="UTC"))));val now=Instant.fromEpochSeconds(serve-705*60);val alerts=cookingAlerts(r,now,zone);assertTrue(alerts.any{it.at==now.epochSeconds&&it.label.contains("Long cook")});assertTrue(alerts.any{it.sourceAt==serve+7*86400});val done=p.copy(progress=listOf(CookingProgress(serve,"a","done",now.epochSeconds)));assertFalse(cookingAlerts(r.copy(data=JsonObject(r.data+("meal_plan" to cookingData(done)))),now,zone).any{it.sourceAt==serve&&it.label.contains("Long cook")});val copy=eventCopyForDate(r.data,LocalDate(2026,11,16),zone);assertEquals(JsonArray(emptyList()),copy["meal_plan"]!!.jsonObject["progress"])}
 @Test fun modernAlarmDefaultsDoNotReinterpretExistingSavedProfiles(){assertEquals(5,AlertProfile().withDeliveryMode(true).duration);val modern=AlertProfile(volume=100).withDeliveryMode(true,true);assertTrue(modern.untilDismissed);assertEquals(0,modern.duration);assertFalse(modern.withDeliveryMode(false,true).untilDismissed);assertEquals(75,WireJson.decodeFromString<AlertProfile>("{}").volume)}
 private fun eventData(serve:Long,p:CookingPlan,repeat:EventRepeat?=null)=obj("title" to "Food".j(),"meal_kind" to "dinner".j(),"all_day" to JsonPrimitive(false),"starts_at" to serve.j(),"ends_at" to JsonNull,"recurrence" to repeatData(repeat),"meal_plan" to cookingData(p))
 @Test fun movingAReadyTimeKeepsTheActualClockAndAlreadyDeliveredCueIdentity(){val serve=1794765600L;val first=cookingSchedule(plan(),serve).first().start;val p=plan().copy(progress=listOf(CookingProgress(serve,"a","running",first)));val before=eventData(serve,p);val after=keepCookingProgress(before,JsonObject(before+("starts_at" to (serve+3600).j())),TimeZone.UTC);val moved=cookingPlan(Record("meal","event",1,after))!!;assertEquals(serve+3600,moved.progress.single().occurrence);assertEquals(first,moved.progress.single().at);assertEquals(first+600*60,cookingSchedule(moved,serve+3600).first{it.stage.id=="a"}.end);val now=Instant.fromEpochSeconds(first+3600);val original=cookingAlerts(Record("meal","event",1,before),now,TimeZone.UTC).filter{it.label.contains("Long cook")}.map{it.key};val updated=cookingAlerts(Record("meal","event",1,after),now,TimeZone.UTC).filter{it.label.contains("Long cook")}.map{it.key};assertEquals(original,updated);assertEquals(serve+3600,cookingAlertOccurrence(Record("meal","event",1,after),original.first(),TimeZone.UTC))}
 @Test fun recurringReadyTimesAndDatesRetainEachOccurrencesProgress(){val serve=1794765600L;val p=plan().copy(progress=listOf(CookingProgress(serve,"a","running",serve-3000),CookingProgress(serve+7*86400,"a","done",serve+7*86400-1000)));val before=eventData(serve,p,EventRepeat("weekly",weekdays=listOf(7),zone="UTC"));val delta=7*86400+3600;val after=keepCookingProgress(before,JsonObject(before+("starts_at" to (serve+delta).j())),TimeZone.UTC);val moved=cookingPlan(Record("m","event",1,after))!!;assertEquals(p.progress.map{it.occurrence+delta},moved.progress.map{it.occurrence});assertEquals(p.progress.map{it.at},moved.progress.map{it.at})}
 @Test fun repeatChangesCannotDetachARunningOccurrence(){val serve=1794765600L;val p=plan().copy(progress=listOf(CookingProgress(serve+7*86400,"a","running",serve+7*86400-1000)));val before=eventData(serve,p,EventRepeat("weekly",weekdays=listOf(7),zone="UTC"));val after=JsonObject(before+("recurrence" to repeatData(EventRepeat("dates",dates=listOf("2026-12-25"),zone="UTC"))));assertFailsWith<IllegalArgumentException>{keepCookingProgress(before,after,TimeZone.UTC)}}

 @Test fun workStartedEarlyStillRemindsWhenTheOccasionIsOutsideTheUsualHorizon(){val zone=TimeZone.UTC;val serve=LocalDateTime(2027,1,17,18,0).toInstant(zone).epochSeconds;val now=Instant.fromEpochSeconds(serve-60*86400);val p=plan().copy(progress=listOf(CookingProgress(serve,"a","running",now.epochSeconds-3600)));val record=Record("future-food","event",1,eventData(serve,p,EventRepeat("weekly",weekdays=listOf(7),zone="UTC")));val alerts=cookingAlerts(record,now,zone);assertTrue(alerts.any{it.sourceAt==serve&&it.at==now.epochSeconds&&it.label.contains("Long cook")});assertTrue(alerts.any{it.sourceAt==serve&&it.at==now.epochSeconds+9*3600&&it.label.contains("Finish")})}

}
